package com.nexttv;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;
/** UI-only checks against the actual minified production Release APK. */
public class DecoderMenuReleaseInstrumentation extends Instrumentation {
 Activity activity;String shotTag="normal";
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null)shotTag=b.getString("shotTag","normal");start();}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String text){if(n==null)return null;n.refresh();if(text.contentEquals(n.getText()==null?"":n.getText()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=find(n.getChild(i),text);if(r!=null)return r;}return null;}
 boolean containsText(AccessibilityNodeInfo n,String text){if(n==null)return false;n.refresh();if(n.getText()!=null&&n.getText().toString().contains(text))return true;for(int i=0;i<n.getChildCount();i++)if(containsText(n.getChild(i),text))return true;return false;}
 AccessibilityNodeInfo waitText(String text)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo n=find(getUiAutomation().getRootInActiveWindow(),text);if(n!=null)return n;SystemClock.sleep(80);}throw new IllegalStateException("Missing "+text);}
 void click(String text)throws Exception{AccessibilityNodeInfo n=waitText(text);while(!n.isClickable())n=n.getParent();if(!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new IllegalStateException("Click "+text);SystemClock.sleep(300);}
 void rendered()throws Exception{long end=SystemClock.uptimeMillis()+45000;while(SystemClock.uptimeMillis()<end){java.io.StringWriter s=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(s),null));java.util.regex.Matcher m=java.util.regex.Pattern.compile("firstFrameMs=(\\d+)").matcher(s.toString());if(m.find()&&Long.parseLong(m.group(1))>0)return;SystemClock.sleep(80);}throw new IllegalStateException("No real first frame");}
 void shot(String name)throws Exception{SystemClock.sleep(600);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image==null)throw new IllegalStateException("No screenshot");android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"nexttv-1.3.29-rows-"+shotTag+"-"+name+".png");v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"image/png");v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IllegalStateException("No screenshot URI");try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 android.graphics.Rect rowBounds(String label)throws Exception{AccessibilityNodeInfo n=waitText(label);AccessibilityNodeInfo target=n;while(target!=null&&!target.isClickable())target=target.getParent();if(target!=null){target.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.getId());SystemClock.sleep(450);n=waitText(label);}while(n!=null){android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);if(r.width()>=260&&r.height()>=40&&r.height()<=180)return r;n=n.getParent();}throw new IllegalStateException("Missing full row "+label);}
 void sameRow(android.graphics.Rect a,android.graphics.Rect b,String label){if(Math.abs(a.width()-b.width())>1||Math.abs(a.height()-b.height())>1)throw new IllegalStateException("Different option sizes "+label+" "+a+" "+b);}
 @Override public void onStart(){int status=Activity.RESULT_OK;String report="";try{
 activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));click("CCTV1综合");rendered();sendKeyDownUpSync(KeyEvent.KEYCODE_MENU);waitText("解码方式");shot("decoder-quick");click("解码方式");waitText("解码方式");waitText("自动");waitText("硬件解码");waitText("软件解码");if(!containsText(getUiAutomation().getRootInActiveWindow(),"优先硬解")||containsText(getUiAutomation().getRootInActiveWindow(),"OMX.")||containsText(getUiAutomation().getRootInActiveWindow(),"Media3"))throw new IllegalStateException("Decoder labels are not human readable");android.graphics.Rect decoderRow=rowBounds("自动");sameRow(decoderRow,rowBounds("硬件解码"),"hardware");sameRow(decoderRow,rowBounds("软件解码"),"software");shot("decoder-dialog");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);SystemClock.sleep(180);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);SystemClock.sleep(400);if(find(getUiAutomation().getRootInActiveWindow(),"解码方式")!=null)throw new IllegalStateException("Decoder choice did not close");rendered();sendKeyDownUpSync(KeyEvent.KEYCODE_MENU);click("解码方式");AccessibilityNodeInfo selected=find(getUiAutomation().getRootInActiveWindow(),"软件解码");while(selected!=null&&!selected.isClickable()&&!selected.isSelected()&&!(selected.isCheckable()&&selected.isChecked()))selected=selected.getParent();if(selected==null||!(selected.isSelected()||selected.isChecked()||containsText(selected,"✓")))throw new IllegalStateException("D-pad did not select software mode past unavailable hardware");shot("decoder-selected");click("自动");rendered();sendKeyDownUpSync(KeyEvent.KEYCODE_MENU);click("音轨");waitText("音轨选择");waitText("自动");waitText("AAC");sameRow(decoderRow,rowBounds("自动"),"audio automatic");sameRow(decoderRow,rowBounds("AAC"),"AAC");shot("audio-dialog");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);SystemClock.sleep(400);sendKeyDownUpSync(KeyEvent.KEYCODE_MENU);click("音轨");waitText("AAC");AccessibilityNodeInfo audio=find(getUiAutomation().getRootInActiveWindow(),"AAC");while(audio!=null&&!audio.isClickable()&&!audio.isSelected()&&!(audio.isCheckable()&&audio.isChecked()))audio=audio.getParent();if(audio==null||!(audio.isSelected()||audio.isChecked()||containsText(audio,"✓")))throw new IllegalStateException("Audio choice/check style did not become effective");shot("audio-selected");click("自动");report="PASS rowBounds="+decoderRow+" fontScale="+getTargetContext().getResources().getConfiguration().fontScale+"; minified Release decoder modes and AAC audio menu share equal row bounds and selected/check style; D-pad skips unsupported hardware, both manual choices and automatic reset work with actual playback\n";
 }catch(Throwable t){status=Activity.RESULT_CANCELED;report=android.util.Log.getStackTraceString(t);}finally{if(activity!=null)runOnMainSync(()->activity.finish());}Bundle b=new Bundle();b.putString("stream",report);finish(status,b);}
}
